#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ByForStmt {
    pub forall_fact: ForallFact,
    pub proof: Vec<Stmt>,
    pub line_file: SourceLine,
}

// What: prove object equality from both `$subset` directions (extensionality).
