//! Stmt and statement variants: IR + display_string.

use super::types::StmtIR;
use crate::ast::stmt::*;
use crate::parse::keywords::*;

macro_rules! impl_display_pair {
    () => {
        pub fn display_string(&self) -> String {
            self.ir().display_string()
        }

        // Human-facing: IR text with `#id#` wrappers stripped.
        pub fn readable_string(&self) -> String {
            crate::display_and_ir::readable_string_from_ir_text(
                self.ir().as_str(),
            )
        }
    };
}

macro_rules! indent {
    ($text:expr, $n:expr) => {{
        let __prefix = "    ".repeat($n);
        ($text)
            .split('\n')
            .map(|line| format!("{}{}", __prefix, line))
            .collect::<Vec<_>>()
            .join(
                "
",
            )
    }};
}

impl Stmt {
