use crate::runtime::{FactId, Runtime};
use crate::store_fact_and_infer::StoreFactAndInferResult;

pub(super) fn project_stmt_detailed(result: &ExecStmtResult, runtime: &Runtime) -> JsonValue {
    match result {
        ExecStmtResult::Fact(fact) => super::entry::project_fact_only(fact, runtime),
        ExecStmtResult::Definition(def) => project_definition(def, runtime),
        ExecStmtResult::Witness(w) => project_witness(w, runtime),
        ExecStmtResult::Trust(t) => project_trust(t, runtime),
        ExecStmtResult::By(b) => project_by(b, runtime),
        ExecStmtResult::Register(r) => project_register(r, runtime),
        ExecStmtResult::ReleaseAndExpand(r) => project_release_and_expand(r, runtime),
        ExecStmtResult::ProofBlock(p) => project_proof_block(p, runtime),
        ExecStmtResult::Command(c) => project_command(c, runtime),
    }
}

fn project_definition(def: &ExecDefinitionStmtResult, runtime: &Runtime) -> JsonValue {
    match def {
        ExecDefinitionStmtResult::DefineObj(d) => project_define_obj(d, runtime),
        ExecDefinitionStmtResult::HaveFnEqual(r) => match r {
            ExecHaveFnEqualStmtResult::Success(s) => object_for(runtime, vec![
                ("success", bool_value(true)),
                ("kind", string("have_fn_equal")),
                ("statement", string(crate::display_and_ir::readable_string_from_ir_text(s.statement.ir().as_str()))),
                ("anonymous_fn_well_defined", project_verify_obj_wd(&s.anonymous_fn_well_defined, runtime)),
                ("fn_set_well_defined", project_verify_obj_wd(&s.fn_set_well_defined, runtime)),
                ("store_and_infer", project_have_store_ids(&s.store_and_infer_result.stored_fact_ids, runtime)),
            ]),
            ExecHaveFnEqualStmtResult::Failed(failed) => {
                let (phase, wd) = match failed {
                    ExecHaveFnEqualStmtFailed::AnonymousFnWellDefined(wd) => ("anonymous_fn_well_defined", wd),
                    ExecHaveFnEqualStmtFailed::FnSetWellDefined(wd) => ("fn_set_well_defined", wd),
                };
                object_for(runtime, vec![
                    ("success", bool_value(false)),
                    ("kind", string("have_fn_equal")),
                    (phase, project_verify_obj_wd(wd, runtime)),
                ])
            }
        },
        ExecDefinitionStmtResult::HaveFnEqualCaseByCase(r) => match r {
            ExecHaveFnEqualCaseByCaseStmtResult::Success(s) => project_success_failed_shell(
                "have_fn_equal_case_by_case", true, Some(s.statement.readable_string()),
                Some(project_have_store_ids(&s.store_and_infer_result.stored_fact_ids, runtime)), runtime,
            ),
            ExecHaveFnEqualCaseByCaseStmtResult::Failed(failure) => object_for(runtime, vec![
                ("success", bool_value(false)), ("kind", string("have_fn_equal_case_by_case")),
                ("failure", project_cases_definition_failure(failure, runtime)),
            ]),
        },
        ExecDefinitionStmtResult::HaveFnByForallExistUnique(r) => {
            use crate::execute::ExecHaveFnByForallExistUniqueStmtFailed;
            match r {
                ExecHaveFnByForallExistUniqueStmtResult::Success(s) => object_for(runtime, vec![
                    ("success", bool_value(true)),
                    ("kind", string("have_fn_by_forall_exist_unique")),
                    ("statement", string(s.statement.readable_string())),
                    ("source_forall", project_verify_fact(&s.source_forall, runtime)),
                    ("fn_set_well_defined", super::wd::project_verify_obj_wd(&s.fn_set_well_defined, runtime)),
                    ("store_and_infer", project_have_store_ids(&s.stored_fact_ids, runtime)),
                ]),
                ExecHaveFnByForallExistUniqueStmtResult::Failed(f) => {
                    let (phase, failure) = match f {
                        ExecHaveFnByForallExistUniqueStmtFailed::SourceForall(v) =>
                            ("source_forall", project_verify_fact(v, runtime)),
                        ExecHaveFnByForallExistUniqueStmtFailed::FnSetWellDefined(v) =>
                            ("fn_set_well_defined", super::wd::project_verify_obj_wd(v, runtime)),
                        ExecHaveFnByForallExistUniqueStmtFailed::PropertyWellDefined(v) =>
                            ("property_well_defined", super::wd_failure::project_fact_wd_failure(v, runtime)),
                    };
                    object_for(runtime, vec![
                        ("success", bool_value(false)),
                        ("kind", string("have_fn_by_forall_exist_unique")),
                        ("phase", string(phase)), ("failure", failure),
                    ])
                }
            }
        },
        ExecDefinitionStmtResult::HaveFnByInduc(r) => project_induc_definition(r, runtime),
        ExecDefinitionStmtResult::DefProp(r) => project_def_prop(r, runtime),
        ExecDefinitionStmtResult::DefAbstractProp(r) => project_def_abstract_prop(r, runtime),
        ExecDefinitionStmtResult::DefStruct(r) => project_def_struct(r, runtime),
        ExecDefinitionStmtResult::DefTemplate(r) => match r {
            ExecDefTemplateStmtResult::Success(s) => object_for(runtime, vec![
                ("success", bool_value(true)),
                ("kind", string("def_template")),
                ("statement", string(s.statement.readable_string())),
                ("definition_facts", JsonValue::Array(s.definition_facts.iter().map(|published| {
                    object_for(runtime, vec![
                        ("source_fact_id", string(published.source_fact_id.to_string())),
                        ("store_and_infer", project_store_and_infer(&published.store_and_infer, runtime)),
                    ])
                }).collect())),
            ]),
            ExecDefTemplateStmtResult::Failed(_) => project_success_failed_shell(
                "def_template", false, None, None, runtime),
        },
        ExecDefinitionStmtResult::DefAlgoByCases(r) => project_success_failed_shell(
            "def_algo_by_cases",
            !r.is_failed(),
            match r {
                ExecDefAlgoByCasesStmtResult::Success(s) => Some(s.statement.readable_string()),
                _ => None,
            },
            None,
            runtime),
        ExecDefinitionStmtResult::DefAlgoByInduc(r) => project_induc_algo(r, runtime),
        ExecDefinitionStmtResult::DefThm(r) => project_def_thm(r, runtime),
        ExecDefinitionStmtResult::Axiom(r) => project_axiom(r, runtime),
        ExecDefinitionStmtResult::DefStrategy(r) => project_def_strategy(r, runtime),
    }
}


fn project_def_thm(result: &ExecDefThmStmtResult, runtime: &Runtime) -> JsonValue {
    match result {
        ExecDefThmStmtResult::Success(s) => object_for(runtime, vec![
            ("success", bool_value(true)),
            ("kind", string("def_thm")),
            (
                "goal_well_defined",
                project_verify_fact_wd_result(&s.goal_wd, runtime),
            ),
            (
                "proof_steps",
                JsonValue::Array(
                    s.proof_steps
                        .iter()
                        .map(|step| project_stmt_detailed(step, runtime))
                        .collect(),
                ),
            ),
            (
                "conclusion_proofs",
                project_verify_facts(&s.conclusion_proofs, runtime),
            ),
                        ("store_and_infer", project_store_and_infer(&s.stored, runtime)),
        ]),
        ExecDefThmStmtResult::Failed(f) => object_for(runtime, vec![
            ("success", bool_value(false)),
            ("kind", string("def_thm")),
            ("failure", super::theorem::project_def_thm_failure(f, runtime)),
        ]),
    }
}

fn project_def_struct(result: &ExecDefStructStmtResult, runtime: &Runtime) -> JsonValue {
    match result {
        ExecDefStructStmtResult::Success(s) => object_for(runtime, vec![
            ("success", bool_value(true)),
            ("kind", string("def_struct")),
            ("statement", string(s.statement.readable_string())),
            ("definition_facts", JsonValue::Array(s.definition_facts.iter().map(|published|
                object_for(runtime, vec![
                    ("source_fact_id", string(published.source_fact_id.to_string())),
                    ("fact_id", string(published.store_and_infer.store.primary_fact_id().to_string())),
                    ("facts", JsonValue::Array(crate::json_output::helper::store_fact_texts(&published.store_and_infer.store)
                        .into_iter().map(string).collect())),
                ])
            ).collect())),
            ("equivalent_facts", JsonValue::Array(s.field_scope.equivalent_facts.iter()
                .zip(&s.statement.equivalent_facts)
                .map(|(proof, fact)| object_for(runtime, vec![
                    ("well_defined", project_fact_wd_proof(&proof.well_defined, runtime)),
                    ("local_store", object_for(runtime, vec![
                        ("fact_id", string(proof.store.primary_fact_id().to_string())),
                        ("fact", string(fact.readable_string())),
                    ])),
                ])).collect())),
        ]),
        ExecDefStructStmtResult::Failed(_) => object_for(runtime, vec![
            ("success", bool_value(false)),
            ("kind", string("def_struct")),
        ]),
    }
}

fn project_axiom(result: &ExecAxiomStmtResult, runtime: &Runtime) -> JsonValue {
    match result {
        ExecAxiomStmtResult::Success(s) => object_for(runtime, vec![
            ("success", bool_value(true)),
            ("kind", string("axiom")),
            (
                "goal_well_defined",
                project_verify_fact_wd_result(&s.goal_wd, runtime),
            ),
            ("store_and_infer", project_store_and_infer(&s.stored, runtime)),
        ]),
        ExecAxiomStmtResult::Failed(_) => object_for(runtime, vec![
            ("success", bool_value(false)),
            ("kind", string("axiom")),
        ]),
    }
}

fn project_def_strategy(result: &ExecDefStrategyStmtResult, runtime: &Runtime) -> JsonValue {
    match result {
        ExecDefStrategyStmtResult::Success(s) => object_for(runtime, vec![
            ("success", bool_value(true)),
            ("kind", string("def_strategy")),
            (
                "goal_well_defined",
                project_verify_fact_wd_result(&s.goal_wd, runtime),
            ),
            (
                "proof_steps",
                project_stmt_steps(&s.proof_steps, runtime),
            ),
            (
                "conclusion_proofs",
                project_verify_facts(&s.conclusion_proofs, runtime),
            ),
                    ]),
        ExecDefStrategyStmtResult::Failed(_) => object_for(runtime, vec![
            ("success", bool_value(false)),
            ("kind", string("def_strategy")),
        ]),
    }
}

fn project_define_obj(def: &ExecDefineObjStmtResult, runtime: &Runtime) -> JsonValue {
    match def {
        ExecDefineObjStmtResult::LetObj(r) => project_let_obj(r, runtime),
        ExecDefineObjStmtResult::HaveObjInNonemptySet(r) => {
            super::entry::project_have_in_nonempty_only(r, runtime)
        }
        ExecDefineObjStmtResult::HaveObjEqual(r) => {
            super::entry::project_have_equal_only(r, runtime)
        }
        ExecDefineObjStmtResult::HaveObjByExistFacts(r) => match r {
            ExecHaveObjByExistFactsStmtResult::Success(s) => object_for(runtime, vec![
                ("success", bool_value(true)),
                ("kind", string("have_obj_by_exist_facts")),
