    let (phase, failure) = match failed {
        ExecDefPropStmtFailed::ParamType(wd) =>
            ("parameter_type", project_verify_obj_wd(wd, runtime)),
        ExecDefPropStmtFailed::AutoOpenStructLayer(failed) => (
            "auto_open_struct_layer",
