                    project_verify_fact_wd_result(&s.goal_wd, runtime),
                ),
                (
                    "proof_steps",
                    JsonValue::Array(
                        s.proof_steps
                            .iter()
                            .map(|step| project_stmt_detailed(step, runtime))
                            .collect(),
                    ),
                ),
                (
                    "conclusion_proofs",
                    project_verify_facts(&s.conclusion_proofs, runtime),
                ),
                                ("stored", project_store_and_infer(&s.stored, runtime)),
            ]),
            ExecClaimStmtResult::Failed(_) => object_for(runtime, vec![
                ("success", bool_value(false)),
                ("kind", string("claim")),
            ]),
        },
        ExecProofBlockStmtResult::Sketch(r) => match r {
            ExecSketchStmtResult::Success(s) => object_for(runtime, vec![
                ("success", bool_value(true)),
                ("kind", string("sketch")),
                (
                    "proof_steps",
                    JsonValue::Array(
                        s.proof_steps
                            .iter()
                            .map(|step| project_stmt_detailed(step, runtime))
                            .collect(),
                    ),
                ),
                            ]),
            ExecSketchStmtResult::Failed(_) => object_for(runtime, vec![
                ("success", bool_value(false)),
                ("kind", string("sketch")),
            ]),
        },
    }
}

fn project_command(result: &ExecCommandStmtResult, runtime: &Runtime) -> JsonValue {
    match result {
        ExecCommandStmtResult::Eval(r) => match r {
            ExecEvalStmtResult::Success(s) => object_for(runtime, vec![
                ("success", bool_value(true)),
                ("kind", string("eval")),
                ("statement", string(s.statement.readable_string())),
                ("aggregate_evaluations", super::aggregate_evaluation::project_aggregate_evaluations(&s.aggregate_evaluations, runtime)),
                ("function_evaluations", super::aggregate_evaluation::project_function_evaluations(&s.function_evaluations, runtime)),
                ("algo_evaluations", super::aggregate_evaluation::project_algo_evaluations(&s.algo_evaluations, runtime)),
                (
                    "source_object",
                    string(s.source_object.readable_string()),
                ),
                ("source_well_defined", project_obj_wd_proof(&s.source_well_defined, runtime)),
                (
                    "rewritten_object",
                    string(s.rewritten_object.readable_string()),
                ),
                (
                    "evaluated_object",
                    string(s.evaluated_object.readable_string()),
                ),
            ]),
            ExecEvalStmtResult::Failed(crate::execute::ExecEvalStmtFailed::WellDefined(failed)) => object_for(runtime, vec![
                ("success", bool_value(false)),
                ("kind", string("eval")),
                ("source_well_defined", project_verify_obj_wd(failed, runtime)),
            ]),
            ExecEvalStmtResult::Failed(crate::execute::ExecEvalStmtFailed::AggregateBudgetExceeded) => object_for(runtime, vec![
                ("success", bool_value(false)), ("kind", string("eval")),
                ("cause", string("aggregate_budget_exceeded")),
            ]),
            ExecEvalStmtResult::Failed(crate::execute::ExecEvalStmtFailed::AggregateRangeOverflow) => object_for(runtime, vec![
                ("success", bool_value(false)), ("kind", string("eval")),
                ("cause", string("aggregate_range_overflow")),
            ]),
            ExecEvalStmtResult::Failed(_) => object_for(runtime, vec![
                ("success", bool_value(false)),
                ("kind", string("eval")),
            ]),
        },
    }
}

fn project_success_failed_shell(
    kind: &str,
    success: bool,
    statement: Option<String>,
    store: Option<JsonValue>,
    runtime: &Runtime,
) -> JsonValue {
    let mut entries = vec![
        ("success", bool_value(success)),
        ("kind", string(kind)),
    ];
    if let Some(stmt) = statement {
        entries.push(("statement", string(stmt)));
    }
    if let Some(store) = store {
        entries.push(("store_and_infer", store));
    }
    object_for(runtime, entries)
}

fn project_fact_ids_as_store(fact_ids: &[FactId], runtime: &Runtime) -> JsonValue {
    project_have_store_ids(fact_ids, runtime)
}

